cases.source:
flowchart LR
A id1@-->B
A@{ shape: 'rect' }

graph TD
A e1@-->B
A uniqueName@-->C
e1@{curve: basis}
uniqueName@{curve: cardinal}

graph TD
A-->B
linkStyle default interpolate basis stroke-width:1px;

graph TD
A-->B
A-->C
linkStyle 0 interpolate basis stroke-width:1px;
linkStyle 1 interpolate cardinal stroke-width:1px;

flowchart TB
      A --> D@{
        shape: circle
        other: "clock"
     }

flowchart TB
      A[hello]
      B@{
        shape: circle
        other: "clock"
     }
      C[Hello]@{
        shape: circle
        other: "clock"
     }

flowchart TB
      A@{
        label: "This is }"
        other: "clock"
     }

flowchart TB
      A@{
        label: "This is a
          multiline string"
        other: "clock"
     }

flowchart TB
      A@{
        label: "This is a string with }"
        other: "clock"
     }

flowchart TB
      A@{
        label: "This is a string with @"
        other: "clock"
     }

flowchart TB
      A@{
        label: "This is a string with}"
        other: "clock"
     }

flowchart TD
    A["A"] --> B["for B"] &    C@{ label: "for c"} & E@{label : "for E"}
    D@{label: "for D"}

flowchart TD
    A["@A@"] --> B["@for@ B@"] & C@{ label: "@for@ c@"} & E{"`@for@ E@`"} & D(("@for@ D@"))
      H1{{"@for@ H@"}}
      H2{{"`@for@ H@`"}}
      Q1{"@for@ Q@"}
      Q2{"`@for@ Q@`"}
      AS1>"@for@ AS@"]
      AS2>"`@for@ AS@`"]

flowchart TD
     A e1@--> B
     C e2@--> D
     E e3@--> F
    e1@{ animate: true }
    e2@{ animate: false }
    e3@{ animate: true }
    e3@{ animate: false }

graph TD;S-->T;
style S background:#aaa;
style T background:#bbb,border:1px solid red;

graph TD
A-->B
classDef exClass font-style:bold;

graph TD;
AA-->BB;
style A fill:#f00;

graph TD
  A[ h ] -- hello --> B[" test "]:::exClass & C --> D;
  classDef exClass background:#bbb,border:1px solid red;
